// src/components/Register.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const Register = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    nom: '',
    email: '',
    password: '',
    role: '',
    class_id: ''
  });
  const [classes, setClasses] = useState([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [classesLoading, setClassesLoading] = useState(true);

  // Récupérer les classes au chargement
  useEffect(() => {
    fetchClasses();
  }, []);

  const fetchClasses = async () => {
    try {
      setClassesLoading(true);
      console.log('🔄 Chargement des classes...');
      
      // Essayer différentes routes possibles pour récupérer les classes
      const possibleRoutes = [
        'http://localhost:5000/api/classes/all',
        'http://localhost:5000/api/classes',
        'http://localhost:5000/api/all-classes',
        'http://localhost:5000/api/professeur/classes/all'
      ];

      let classesData = [];

      for (const route of possibleRoutes) {
        try {
          console.log(`🔍 Essai de la route: ${route}`);
          const response = await fetch(route);
          
          if (response.ok) {
            const data = await response.json();
            // Gérer différents formats de réponse
            classesData = data.classes || data || [];
            console.log(`✅ Classes chargées via ${route}:`, classesData.length);
            break;
          }
        } catch (error) {
          console.log(`❌ Route ${route} échouée:`, error.message);
          continue;
        }
      }

      if (classesData.length === 0) {
        console.log('⚠️ Aucune classe trouvée via les routes testées');
        // Données de démonstration pour le test
        classesData = [
          {
            id: 1,
            nom: 'Classe de Mathématiques',
            niveau: 'Terminale',
            annee_scolaire: '2023-2024',
            professeur_nom: 'M. Dupont'
          },
          {
            id: 2,
            nom: 'Classe de Physique',
            niveau: 'Première',
            annee_scolaire: '2023-2024',
            professeur_nom: 'Mme Martin'
          }
        ];
        console.log('📚 Données de démonstration chargées');
      }

      setClasses(classesData);
      
    } catch (error) {
      console.error('❌ Erreur chargement classes:', error);
      // Charger des données de démonstration en cas d'erreur
      setClasses([
        {
          id: 1,
          nom: 'Classe de Mathématiques',
          niveau: 'Terminale',
          annee_scolaire: '2023-2024',
          professeur_nom: 'M. Dupont'
        },
        {
          id: 2,
          nom: 'Classe de Physique',
          niveau: 'Première',
          annee_scolaire: '2023-2024',
          professeur_nom: 'Mme Martin'
        }
      ]);
    } finally {
      setClassesLoading(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ 
      ...prev, 
      [name]: value 
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    // Validation supplémentaire pour les étudiants
    if (formData.role === 'student' && !formData.class_id) {
      setMessage('❌ Veuillez sélectionner une classe pour les étudiants');
      setLoading(false);
      return;
    }

    try {
      const response = await fetch('http://localhost:5000/api/auth/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData)
      });

      const result = await response.json();

      if (response.ok && result.success) {
        setMessage('✅ Compte créé avec succès! Vous allez être redirigé vers la page de connexion...');
        
        // Redirection après 3 secondes pour laisser voir le message
        setTimeout(() => {
          navigate('/login');
        }, 3000);
        
      } else {
        setMessage(`❌ Erreur: ${result.message || 'Erreur lors de la création du compte'}`);
      }
    } catch (error) {
      setMessage('❌ Erreur de connexion au serveur');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ 
      maxWidth: '500px', 
      margin: '50px auto', 
      padding: '30px',
      background: 'white',
      borderRadius: '12px',
      boxShadow: '0 4px 20px rgba(0, 0, 0, 0.1)'
    }}>
      <h2 style={{ 
        textAlign: 'center', 
        color: '#2d3748',
        marginBottom: '30px',
        fontSize: '2rem'
      }}>
        📝 Inscription
      </h2>
      
      {message && (
        <div style={{
          padding: '15px',
          backgroundColor: message.includes('✅') ? '#d4edda' : '#f8d7da',
          color: message.includes('✅') ? '#155724' : '#721c24',
          borderRadius: '8px',
          marginBottom: '20px',
          border: `1px solid ${message.includes('✅') ? '#c3e6cb' : '#f5c6cb'}`
        }}>
          {message}
        </div>
      )}

      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: '20px' }}>
          <label style={{ display: 'block', marginBottom: '5px', fontWeight: '600', color: '#4a5568' }}>
            👤 Nom complet *
          </label>
          <input
            type="text"
            name="nom"
            value={formData.nom}
            onChange={handleInputChange}
            required
            style={{ 
              width: '100%', 
              padding: '12px', 
              border: '2px solid #e2e8f0',
              borderRadius: '8px',
              fontSize: '16px',
              transition: 'border-color 0.3s'
            }}
            onFocus={(e) => e.target.style.borderColor = '#667eea'}
            onBlur={(e) => e.target.style.borderColor = '#e2e8f0'}
          />
        </div>

        <div style={{ marginBottom: '20px' }}>
          <label style={{ display: 'block', marginBottom: '5px', fontWeight: '600', color: '#4a5568' }}>
            📧 Email *
          </label>
          <input
            type="email"
            name="email"
            value={formData.email}
            onChange={handleInputChange}
            required
            style={{ 
              width: '100%', 
              padding: '12px', 
              border: '2px solid #e2e8f0',
              borderRadius: '8px',
              fontSize: '16px',
              transition: 'border-color 0.3s'
            }}
            onFocus={(e) => e.target.style.borderColor = '#667eea'}
            onBlur={(e) => e.target.style.borderColor = '#e2e8f0'}
          />
        </div>

        <div style={{ marginBottom: '20px' }}>
          <label style={{ display: 'block', marginBottom: '5px', fontWeight: '600', color: '#4a5568' }}>
            🔒 Mot de passe *
          </label>
          <input
            type="password"
            name="password"
            value={formData.password}
            onChange={handleInputChange}
            required
            minLength="6"
            style={{ 
              width: '100%', 
              padding: '12px', 
              border: '2px solid #e2e8f0',
              borderRadius: '8px',
              fontSize: '16px',
              transition: 'border-color 0.3s'
            }}
            onFocus={(e) => e.target.style.borderColor = '#667eea'}
            onBlur={(e) => e.target.style.borderColor = '#e2e8f0'}
          />
        </div>

        <div style={{ marginBottom: '20px' }}>
          <label style={{ display: 'block', marginBottom: '5px', fontWeight: '600', color: '#4a5568' }}>
            🎭 Rôle *
          </label>
          <select
            name="role"
            value={formData.role}
            onChange={handleInputChange}
            required
            style={{ 
              width: '100%', 
              padding: '12px', 
              border: '2px solid #e2e8f0',
              borderRadius: '8px',
              fontSize: '16px',
              backgroundColor: 'white',
              transition: 'border-color 0.3s'
            }}
            onFocus={(e) => e.target.style.borderColor = '#667eea'}
            onBlur={(e) => e.target.style.borderColor = '#e2e8f0'}
          >
            <option value="">Sélectionnez un rôle</option>
            <option value="student">Étudiant</option>
            <option value="professeur">Professeur</option>
          </select>
        </div>

        {/* Champ classe - seulement visible pour les étudiants */}
        {formData.role === 'student' && (
          <div style={{ marginBottom: '20px' }}>
            <label style={{ display: 'block', marginBottom: '5px', fontWeight: '600', color: '#4a5568' }}>
              🏫 Classe *
            </label>
            
            {classesLoading ? (
              <div style={{ 
                padding: '15px', 
                backgroundColor: '#f8fafc', 
                color: '#4a5568',
                borderRadius: '8px',
                textAlign: 'center',
                border: '2px dashed #cbd5e0'
              }}>
                <div style={{ 
                  width: '20px', 
                  height: '20px', 
                  border: '2px solid #667eea',
                  borderTop: '2px solid transparent',
                  borderRadius: '50%',
                  animation: 'spin 1s linear infinite',
                  margin: '0 auto 10px'
                }}></div>
                Chargement des classes...
              </div>
            ) : classes.length === 0 ? (
              <div style={{ 
                padding: '15px', 
                backgroundColor: '#fffaf0', 
                color: '#744210',
                borderRadius: '8px',
                border: '1px solid #fed7aa',
                textAlign: 'center'
              }}>
                ⚠️ Aucune classe disponible pour le moment.
                <br />
                <small>Contactez l'administrateur pour créer une classe.</small>
              </div>
            ) : (
              <>
                <select
                  name="class_id"
                  value={formData.class_id}
                  onChange={handleInputChange}
                  required
                  style={{ 
                    width: '100%', 
                    padding: '12px', 
                    border: '2px solid #e2e8f0',
                    borderRadius: '8px',
                    fontSize: '16px',
                    backgroundColor: 'white',
                    marginBottom: '10px',
                    transition: 'border-color 0.3s'
                  }}
                  onFocus={(e) => e.target.style.borderColor = '#667eea'}
                  onBlur={(e) => e.target.style.borderColor = '#e2e8f0'}
                >
                  <option value="">Sélectionnez une classe</option>
                  {classes.map(classe => (
                    <option key={classe.id} value={classe.id}>
                      {classe.nom || classe.name} - {classe.niveau} 
                      {classe.annee_scolaire && ` (${classe.annee_scolaire})`}
                      {classe.professeur_nom && ` - ${classe.professeur_nom}`}
                    </option>
                  ))}
                </select>
                <div style={{ 
                  fontSize: '0.8rem', 
                  color: '#718096',
                  textAlign: 'center'
                }}>
                  📚 {classes.length} classe{classes.length > 1 ? 's' : ''} disponible{classes.length > 1 ? 's' : ''}
                </div>
              </>
            )}
          </div>
        )}

        <button 
          type="submit" 
          disabled={loading || (formData.role === 'student' && !formData.class_id && !classesLoading)}
          style={{
            width: '100%',
            padding: '15px',
            backgroundColor: loading ? '#a0aec0' : '#667eea',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            cursor: (loading || (formData.role === 'student' && !formData.class_id && !classesLoading)) ? 'not-allowed' : 'pointer',
            fontSize: '16px',
            fontWeight: '600',
            transition: 'background-color 0.3s'
          }}
        >
          {loading ? '⏳ Création en cours...' : '📝 Créer le compte'}
        </button>
      </form>

      {/* Lien vers login */}
      <div style={{ textAlign: 'center', marginTop: '25px', paddingTop: '20px', borderTop: '1px solid #e2e8f0' }}>
        <p style={{ color: '#718096', margin: 0 }}>
          Déjà un compte ? 
          <button 
            onClick={() => navigate('/login')}
            style={{
              background: 'none',
              border: 'none',
              color: '#667eea',
              cursor: 'pointer',
              textDecoration: 'underline',
              marginLeft: '5px',
              fontWeight: '600'
            }}
          >
            Se connecter
          </button>
        </p>
      </div>
    </div>
  );
};

// Ajouter les keyframes CSS pour l'animation de chargement
const style = document.createElement('style');
style.textContent = `
  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
`;
document.head.appendChild(style);

export default Register;
